/* ===== RESET ===== */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: sans-serif;
  background: #1a1a1a;
  color: white;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100vh;
}

h1 {
  position: absolute;
  top: 30px;
  font-size: 2.5em;
  letter-spacing: 3px;
  color: #fff;
}

.move-counter {
  position: absolute;
  top: 100px;
  font-size: 1.2em;
  color: #aaa;
}

/* ===== SCENE ===== */
#scene {
  width: 400px;
  height: 400px;
  perspective: 1200px;
  position: relative;
  margin-bottom: 150px;
}

/* ===== CUBE STATES ===== */
[id^="cubeState_"] {
  display: none;
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transform: rotateX(-20deg) rotateY(30deg);
}

