.move-btn {
  padding: 15px 25px;
  background: #333;
  color: white;
  border: 3px solid #666;
  border-radius: 8px;
  cursor: pointer;
  font-weight: bold;
  font-size: 1.1em;
  transition: all 0.2s;
  text-decoration: none;
  display: block;
}

.move-btn:hover {
  background: #444;
  border-color: #999;
  transform: scale(1.05);
}

.move-btn:active {
  transform: scale(0.95);
}

/* Move button colors */
.move-L { border-color: #a2a2a2; color: #ffffff; }
.move-R { border-color: #a2a2a2; color: #ffffff; }
.move-U { border-color: #a2a2a2; color: #ffffff; }
.move-B { border-color: #a2a2a2; color: #ffffff; }

/* Hide radio inputs */
input[type="radio"] { display: none; }
